import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    id("net.fabricmc.fabric-loom")
    id("org.jetbrains.kotlin.jvm") version "2.4.10"
    id("com.google.devtools.ksp") version "2.3.11"

    `maven-publish`
}

version = "${property("mod.version")}+${sc.current.version}"
group = property("mod.group") as String
base.archivesName = property("mod.id") as String

sourceSets {
    // sources autogenerated resources
    main {
        resources {
            // get from versions
            srcDirs(layout.buildDirectory.dir("generated/resources"))
        }
    }
}

repositories {
    // Add repositories to retrieve artifacts from in here.
    maven("https://pkgs.dev.azure.com/djtheredstoner/DevAuth/_packaging/public/maven/v1")
    maven("https://maven.shedaniel.me/")
    maven("https://maven.terraformersmc.com/") { name = "Terraformers" }
    maven("https://maven.teamresourceful.com/repository/maven-public/") { name = "Resourceful" }
}

dependencies {
    // minecraft version
    minecraft("com.mojang:minecraft:${sc.current.version}")

    // independent deps
    implementation("net.fabricmc:fabric-loader:${property("deps.fabric_loader")}")
    implementation("net.fabricmc:fabric-language-kotlin:${property("deps.fabric_language_kotlin")}")

    // dev-auth
    runtimeOnly("me.djtheredstoner:DevAuth-fabric:${property("deps.devauth")}")

    // dependent deps
    implementation("net.fabricmc.fabric-api:fabric-api:${property("deps.fabric_api")}")
    implementation("me.shedaniel.cloth:cloth-config-fabric:${property("deps.cloth_config")}")
    implementation("com.terraformersmc:modmenu:${property("deps.modmenu")}")

    // KtModules
    compileOnly("me.owdding.ktmodules:KtModules:${property("deps.ktmodules")}")
    ksp("me.owdding.ktmodules:KtModules:${property("deps.ktmodules")}")
}

ksp {
    arg("meowdding.modules.project_name", base.archivesName)
    arg("meowdding.modules.package", "pet.itpuppy.woasts.generated")
}

tasks.register<FlattenLangTask>("flattenLang") {
    description = "Flattens language .json files and stores them in the specified folder."

    // get from root, store in versions
    val input = rootProject.file("src/main/lang")
    val output = layout.buildDirectory.dir("generated/resources/assets/${rootProject.name}/lang")

    inputDir.set(input)
    outputDir.set(output)
}

tasks.processResources {
    // maps provided variables to .json templates to put into fabric.mod.json
    fun MutableMap<String, String>.register(key: String, property: String) {
        val value: String = sc.properties[property]
        inputs.property(key, value)
        set(key, value)
    }

    // specify vars to pass into fabric.mod.json here
    val props = buildMap {
        // mod metadata
        register("mod_id", "mod.id")
        register("mod_name", "mod.name")
        register("mod_version", "mod.version")
        register("mod_mc_compat", "mod.mc_compat")
        register("mod_desc", "mod.desc")

        // deps
        register("deps_cloth_config", "deps.cloth_config")
    }

    filesMatching("fabric.mod.json") { expand(props) }
    dependsOn("flattenLang")
}

val mcVersion = sc.current.version.replace(".", "")
loom {
    runConfigs["client"].apply {
        ideConfigGenerated(true)
        runDir = "../../run"
        vmArg("-Dfabric.modsFolder=\"${mcVersion}Mods\"")
    }
    accessWidenerPath = rootProject.file("src/main/resources/woasts.classtweaker")
}

tasks.withType<JavaCompile>().configureEach {
    options.release = 25
}

kotlin {
    compilerOptions {
        jvmTarget = JvmTarget.JVM_25
    }
}

java {
    withSourcesJar()

    sourceCompatibility = JavaVersion.VERSION_25
    targetCompatibility = JavaVersion.VERSION_25
}

tasks.jar {
    destinationDirectory.set(rootProject.file("build/libs"))

    val projectName = project.name
    inputs.property("projectName", projectName)

    from("LICENSE") {
        rename { "${it}_$projectName" }
    }
}

tasks.named("sourcesJar") {
    // needed for proper building

    dependsOn("flattenLang")
}

publishing {
    // configure the maven publication

    publications {
        register<MavenPublication>("mavenJava") {
            from(components["java"])
        }
    }

    // See https://docs.gradle.org/current/userguide/publishing_maven.html for information on how to set up publishing.
    repositories { }
}
